  function settingsScreen(){return `${pageHead('Настройки организации','Часовой пояс, контрольные пороги, уведомления, безопасность и интеграции.',btn('Сохранить изменения','check','primary'))}<div class="tabs"><div class="tab active">Общие</div><div class="tab">Безопасность</div><div class="tab">Уведомления</div><div class="tab">Интеграции</div><div class="tab">Импорт / экспорт</div></div><div class="grid cols-2"><div class="card"><div class="card-head"><h3>Общие параметры</h3></div><div class="form-grid"><div class="field"><label>Название организации</label><input value="ООО ЧОП «Оберег»"></div><div class="field"><label>Часовой пояс</label><select><option>Europe/Moscow</option></select></div><div class="field"><label>Радиус геозоны по умолчанию</label><input value="120 м"></div><div class="field"><label>Порог NO_SHOW</label><input value="10 мин"></div></div></div><div class="card"><div class="card-head"><h3>Правила доступа</h3></div>${mini('shield','MFA для привилегированных ролей','Включено','success')}${mini('clock','Время сессии','12 часов','info')}${mini('lock','Break-glass','Требует причины и срока','info')}</div></div><div class="card section"><div class="card-head"><h3>Интеграции</h3></div><div class="grid cols-4">${['SMS / OTP','Mobile Push','S3 Storage','Карты / геокодер'].map((x,i)=>`<div class="m-card"><strong>${x}</strong><p>${i<2?'Подключено':'Настроено'}</p>${pill('OK','success')}</div>`).join('')}</div></div>`}

  function usersRoles(kind){
    if(kind==='users') return `${pageHead('Пользователи','Учетные записи, статусы, MFA, роли и привязка к сотрудникам.',btn('Пригласить пользователя','plus','primary'))}${searchToolbar('Email, имя, роль...')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Пользователь</th><th>Роль</th><th>MFA</th><th>Scope</th><th>Статус</th></tr></thead><tbody>${row('Алексей Сергеев','admin@chop.ru',['Владелец / директор',pill('ON','success'),'Все объекты',pill('ACTIVE','success')],null)}${row('Мария Кузнецова','hr@chop.ru',['Кадровик',pill('ON','success'),'Все объекты',pill('ACTIVE','success')],null)}${row('Максим Сидоров','head@chop.ru',['Начальник объекта',pill('ON','success'),'Склад №7',pill('ACTIVE','success')],null)}${row('Аудитор','audit@chop.ru',['Auditor read-only',pill('ON','success'),'БЦ Север · до 03.10',pill('ACTIVE','success')],null)}</tbody></table></div>`;
    return `${pageHead('Роли и права','RBAC, atomic permissions, object scope и срок назначения.',btn('Создать роль','plus','primary'))}<div class="grid cols-3"><div class="card"><div class="card-head"><h3>Администратор ЧОП</h3>${tag('System')}</div><p style="color:var(--muted)">Пользователи, роли, справочники, объекты и настройки.</p><div>${tag('users.manage','primary')} ${tag('facilities.manage','primary')} ${tag('roles.manage','primary')}</div></div><div class="card"><div class="card-head"><h3>Начальник объекта</h3>${tag('Scoped')}</div><p style="color:var(--muted)">Смены, сотрудники и инциденты только назначенных объектов.</p><div>${tag('shifts.manage','primary')} ${tag('incidents.manage','primary')}</div></div><div class="card"><div class="card-head"><h3>Представитель заказчика</h3>${tag('Client')}</div><p style="color:var(--muted)">Только опубликованные данные по своим объектам.</p><div>${tag('reports.read','primary')} ${tag('coverage.read','primary')}</div></div></div><div class="card section"><div class="card-head"><h3>Матрица permissions</h3></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Permission</th><th>Admin</th><th>Operations</th><th>HR</th><th>Head</th><th>Client</th></tr></thead><tbody>${[['employees.read','✓','✓','✓','✓','—'],['employees.manage','✓','—','✓','—','—'],['facilities.manage','✓','✓','—','scope','—'],['reports.read','✓','✓','—','scope','scope'],['audit.read','✓','scope','—','—','—']].map(r=>`<tr>${r.map((x,i)=>`<td>${i?tag(x,x==='✓'?'primary':''): `<strong>${x}</strong>`}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;
  }

  function renderAdmin(id){
    if(id==='login'||id==='mfa')return authScreen('admin',id);
    let content;
    if(id==='dashboard')content=adminDashboard();
    else if(['employees','documents','customers','facilities','posts','assignments','patrols','incidents','notifications','audit'].includes(id))content=listScreen(id);
    else if(id==='employee')content=employeeDetail();
    else if(['licenses','contracts','compliance'].includes(id))content=legalScreen(id);
    else if(id==='customer')content=customerDetail();
    else if(id==='facility')content=facilityDetail();
    else if(id==='post')content=postDetail();
    else if(id==='schedule')content=scheduleScreen();
    else if(id==='shift')content=shiftDetail();
    else if(id==='attendance')content=attendanceScreen();
    else if(id==='patrol')content=patrolDetail();
    else if(id==='incident')content=incidentDetail();
    else if(id==='reports')content=reportsScreen();
    else if(id==='settings')content=settingsScreen();
    else if(id==='users'||id==='roles')content=usersRoles(id);
    else content=adminDashboard();
    return shell('admin',id,content);
  }
